source(file.path(dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value=TRUE)[1]), mustWork=FALSE)), "backend_common.R"))
opts<-parse_cli_args(); require_args(opts,c("vectors","outdir")); d<-readr::read_tsv(opts$vectors,show_col_types=FALSE); cols<-grep("^a",names(d),value=TRUE); if(!all(c("subject_id",cols)%in%names(d)))stop("vectors require subject_id and a1/a2... plus e1/e2...",call.=FALSE); ecol<-sub("^a","e",cols); A<-as.matrix(d[,cols]); E<-as.matrix(d[,ecol]); q<-vapply(seq_len(nrow(d)),function(i)cosine_similarity(E[i,],-A[i,]),numeric(1)); rho<-sqrt(rowSums(E^2))/sqrt(rowSums(A^2)); write_tsv_safe(tibble(subject_id=d$subject_id,q_return_orientation=q,rho_residual_to_away=rho,interpretation="positive q indicates return-oriented movement, not complete recovery"),file.path(ensure_outdir(opts$outdir),"longitudinal_return_geometry.tsv"))
